SELECT COUNT(1)
FROM login_security_logs
WHERE host_id = #{hostId}
  AND login_result = 'fail'
  AND username = #{username}
  AND event_time >= #{since}
  AND event_time <= #{until}

    AND source_ip = #{sourceIp}

SELECT DISTINCT username
FROM login_security_logs
WHERE host_id = #{hostId}
  AND login_result = 'fail'
  AND source_ip = #{sourceIp}
  AND event_time >= #{since}
  AND event_time <= #{until}
  AND username IS NOT NULL
  AND username != ''
